"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["11833"],{81526(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.endereco_referencia.cep_obrigatorio","status":422,"titulo":"CEP \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.endereco_referencia.cep_obrigatorio","requisitos":[],"oQueAconteceu":["O endere\xe7o estruturado foi enviado sem o CEP: o campo `cep` est\xe1 ausente, nulo, vazio ou s\xf3 com espa\xe7os. A mensagem \xe9 `CEP do endere\xe7o \xe9 obrigat\xf3rio.` O CEP \xe9 a primeira confer\xeancia do endere\xe7o, e sem ele a API n\xe3o confere mais nada do objeto.","O endere\xe7o estruturado \xe9 opcional no cadastro do campus, do local de oferta e da institui\xe7\xe3o (a sede): sem o objeto `endereco` no corpo da requisi\xe7\xe3o, nenhuma confer\xeancia dele ocorre. Com o objeto, a API confere os campos um de cada vez e para na primeira recusa, nesta ordem: CEP informado, CEP com 8 d\xedgitos, cidade do endere\xe7o (as recusas da fam\xedlia [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio)), tamanho dos textos (logradouro, n\xfamero, complemento, bairro e distrito), latitude, longitude, n\xedvel de resolu\xe7\xe3o informado, n\xedvel de resolu\xe7\xe3o dentro do vocabul\xe1rio, origem informada e tamanho da origem.","A recusa vem na lista `errors` da resposta, com `field` igual a `endereco`, ao lado das recusas dos outros campos do mesmo cadastro, que s\xe3o conferidos no mesmo pedido. O `code` da resposta \xe9 o da primeira recusa da lista, e as recusas dos campos do pr\xf3prio cadastro (como `sigla`, `nome` e a cidade) v\xeam antes da do endere\xe7o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, estas confer\xeancias v\xeam antes da busca do registro: um `{id}` que n\xe3o existe, enviado com endere\xe7o recusado, recebe esta recusa, e s\xf3 o corpo aceito chega \xe0 resposta de [campus n\xe3o encontrado](/erros/uniplus.configuracao.campus.nao_encontrado), de [local de oferta n\xe3o encontrado](/erros/uniplus.configuracao.local_oferta.nao_encontrado) ou de [institui\xe7\xe3o n\xe3o encontrada](/erros/uniplus.organizacao.instituicao.nao_encontrada)."],"comoResolver":["Informe o `cep` com 8 d\xedgitos dentro do objeto `endereco`, ou retire o objeto `endereco` do corpo se o cadastro n\xe3o tiver endere\xe7o estruturado a declarar."],"ondeAparece":["Cria\xe7\xe3o de um campus","Atualiza\xe7\xe3o de um campus","Cria\xe7\xe3o de um local de oferta","Atualiza\xe7\xe3o de um local de oferta","Cria\xe7\xe3o da institui\xe7\xe3o","Atualiza\xe7\xe3o da institui\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Endereco referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);